package com.example.sploot.ml

/**
 * 1:1 port of `ml_pipeline/ibi_seq.py` — the raw-IBI preprocessing shared with
 * training. Must stay bit-compatible with the Python version (see
 * `IbiSequencePreprocessorTest` golden vectors generated by the Python module).
 *
 * Pipeline:
 *  1. beats (tMs, ibiMs) -> drop IBI outside [300, 2000] ms
 *  2. drop beats deviating >20 % from the positional 5-beat median (ectopics)
 *  3. 2 Hz grid starting at session start, nEpochs*60 samples; linear
 *     interpolation with edges held (np.interp semantics)
 *  4. ch0: z-score of interpolated IBI (night mean / std, std floor 1 ms)
 *     ch1: quality mask = 1 if a valid beat lies within ±5 s of the sample
 */
object IbiSequencePreprocessor {

    const val FS = 2.0
    const val EPOCH_S = 30
    const val SAMPLES_PER_EPOCH = 60
    const val MIN_IBI_MS = 300.0
    const val MAX_IBI_MS = 2000.0
    const val GAP_MS = 5_000.0
    const val ECTOPIC_DEVIATION = 0.2
    private const val MEDIAN_WINDOW = 5

    /**
     * @param beats raw (timestampMs, intervalMs) pairs; order not required.
     * @return FloatArray of length 2*nEpochs*60 laid out channel-major
     *   ([0..n) = z-scored IBI, [n..2n) = validity mask), or null when fewer
     *   than 10 clean beats survive (matching the Python `x.size < 10` guard;
     *   the caller falls back to a feature-based engine).
     */
    fun toSequence(beats: List<Pair<Long, Int>>, startMs: Long, nEpochs: Int): FloatArray? {
        val n = nEpochs * SAMPLES_PER_EPOCH
        val sorted = beats.sortedBy { it.first }
        var t = ArrayList<Double>(sorted.size)
        var x = ArrayList<Double>(sorted.size)
        for ((ts, ibi) in sorted) {
            val v = ibi.toDouble()
            if (v in MIN_IBI_MS..MAX_IBI_MS) {
                t.add(ts.toDouble()); x.add(v)
            }
        }
        val kept = ectopicFilter(t, x)
        t = kept.first; x = kept.second
        if (x.size < 10) return null

        val grid = DoubleArray(n) { startMs + (it + 0.5) * (1000.0 / FS) }
        val y = interp(grid, t.toDoubleArray(), x.toDoubleArray())
        var mu = 0.0
        for (v in x) mu += v
        mu /= x.size
        var ss = 0.0
        for (v in x) ss += (v - mu) * (v - mu)
        val sd = kotlin.math.sqrt(ss / x.size)
        val denom = maxOf(sd, 1.0)

        val out = FloatArray(2 * n)
        val ts = t.toDoubleArray()
        for (k in 0 until n) {
            out[k] = ((y[k] - mu) / denom).toFloat()
            val (lo, hi) = bracket(ts, grid[k])
            val dLo = kotlin.math.abs(grid[k] - ts[lo])
            val dHi = kotlin.math.abs(ts[hi] - grid[k])
            out[n + k] = if (minOf(dLo, dHi) <= GAP_MS) 1f else 0f
        }
        return out
    }

    /** Python: drop |x - median(x[i-2..i+2])| > 0.2*median (NaN pad edges). */
    private fun ectopicFilter(
        t: ArrayList<Double>,
        x: ArrayList<Double>,
    ): Pair<ArrayList<Double>, ArrayList<Double>> {
        val n = x.size
        if (n < MEDIAN_WINDOW) return t to x
        val half = MEDIAN_WINDOW / 2
        val outT = ArrayList<Double>(n)
        val outX = ArrayList<Double>(n)
        for (i in 0 until n) {
            val win = ArrayList<Double>(MEDIAN_WINDOW)
            for (j in maxOf(0, i - half)..minOf(n - 1, i + half)) win.add(x[j])
            val med = median(win)
            if (kotlin.math.abs(x[i] - med) <= ECTOPIC_DEVIATION * med) {
                outT.add(t[i]); outX.add(x[i])
            }
        }
        return outT to outX
    }

    private fun median(v: List<Double>): Double {
        val s = v.sorted()
        val m = s.size / 2
        return if (s.size % 2 == 1) s[m] else (s[m - 1] + s[m]) / 2.0
    }

    /** np.interp: linear interpolation, values held constant outside [t0, tn]. */
    private fun interp(grid: DoubleArray, t: DoubleArray, x: DoubleArray): DoubleArray {
        val out = DoubleArray(grid.size)
        for (k in grid.indices) {
            val g = grid[k]
            out[k] = when {
                g <= t.first() -> x.first()
                g >= t.last() -> x.last()
                else -> {
                    val (lo, hi) = bracket(t, g)
                    val span = t[hi] - t[lo]
                    if (span <= 0) x[lo]
                    else x[lo] + (x[hi] - x[lo]) * (g - t[lo]) / span
                }
            }
        }
        return out
    }

    /** Indices (lo, hi) with t[lo] <= g <= t[hi]; lo == hi at exact hits. */
    private fun bracket(t: DoubleArray, g: Double): Pair<Int, Int> {
        var lo = 0
        var hi = t.size - 1
        while (hi - lo > 1) {
            val mid = (lo + hi) ushr 1
            if (t[mid] <= g) lo = mid else hi = mid
        }
        return lo to hi
    }
}
